using System;
using System.Collections.Generic;
using System.Data;

using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using Sunplus.Accounting.Core.Common;



namespace Sunplus.Accounting.Business.PositionTaking.SportBook
{
    /// <summary>
    /// Summary description for SuperPT
    /// </summary>
    public class SuperPT : BasePT
    {
        public override string Select(PtManager.PtType ptType)
        {
            try
            {
                string result = "";

                //DataTable dtResult = SiteProvider.PositionTaking.SportBook.Select(ptType);
                IEnumerable<int> lsSportId = Constants.Sport.Sports;

                var data = new DataTable();

                foreach (int sportId in lsSportId)
                {
                    OutputData[Constants.Sport.GetSportName(sportId)] =
                        new JValue(JsonConvert.SerializeObject(GetSportPt(sportId, ptType, data)));
                }

                return base.Select(ptType);
            }
            catch (Exception ex)
            {
                Sunplus.Accounting.Core.Extensions.LogExtensions.ExceptionHandler(ex);
                return string.Empty;
            }
        }

        private static string AddNew(IEnumerable<int> betTypes, DataTable data)
        {
            var jBetTypes = new JObject();
            foreach (int betType in betTypes)
            {
                string betTypeName = Constants.BetType.GetBetTypeName(betType);
                var betTypeDetail = new BettypeDetail
                                        {
                                            SuperMaxPt = MaxPT,
                                            SuperMinPt = MinPT,
                                            MasterMaxPt = MaxPT,
                                            MasterMinPt = MinPT,
                                            AgentMaxPt = MaxPT,
                                            AgentMinPt = MinPT
                                        };
                jBetTypes[betTypeName] = new JValue(JsonConvert.SerializeObject(betTypeDetail));
            }
            return JsonConvert.SerializeObject(jBetTypes);
        }

        protected override SportDetail GetSportPt(int sportId, PtManager.PtType ptType, DataTable data)
        {
            string betTypes = "";
            IEnumerable<int> lsBetTypes = Constants.BetType.SoccerBettypes;
            switch (ptType)
            {
                case PtManager.PtType.AddNewSuper:
                    betTypes = AddNew(lsBetTypes, data);
                    break;
            }
            return new SportDetail(Constants.Sport.GetSportName(sportId), sportId, betTypes);
        }

        protected override SportDetail Soccer(PtManager.PtType ptType, DataTable data)
        {
            string betTypes = "";
            switch (ptType)
            {
                case PtManager.PtType.AddNewSuper:
                    betTypes = AddNew(Constants.BetType.SoccerBettypes, data);
                    break;
            }
            return new SportDetail(Constants.Sport.GetSportName(Constants.Sport.Soccer), Constants.Sport.Soccer, betTypes);
        }
    }
}